// 11. Planar — mesh() early exit: 2 triangles
let planar = NurbsCurve::create(false, 1, &[Point::new(0.0, 132.0, 0.0), Point::new(6.0, 132.0, 0.0), Point::new(6.0, 136.0, 0.0), Point::new(0.0, 136.0, 0.0), Point::new(0.0, 132.0, 0.0)]);
